-- ----------------------------
-- Table structure for vd_check
-- ----------------------------
DROP TABLE IF EXISTS `vd_check`;
CREATE TABLE `vd_check`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户id',
  `duty` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '责任人',
  `duty_tel` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '责任人联系方式',
  `place` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
  `create_time` datetime NOT NULL COMMENT '检查时间',
  `update_time` datetime NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `time` datetime NULL DEFAULT NULL COMMENT '时间',
  `d_time` int(11) NULL DEFAULT NULL COMMENT '持续时间',
  `situation` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '检查情况',
  `score` tinyint(1) NULL DEFAULT NULL COMMENT '评分： 0很差 1差 2中等 3良好 4优秀',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除 0没删 1删',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

