-- ----------------------------
-- Table structure for vd_device
-- ----------------------------
DROP TABLE IF EXISTS `vd_device`;
CREATE TABLE `vd_device`  (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户id',
  `place_id` bigint(20) UNSIGNED NOT NULL COMMENT '地点id',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '设备名字',
  `pic` bigint(20) NULL DEFAULT NULL COMMENT '照片地址',
  `res` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '来源',
  `duty` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '责任人',
  `duty_tel` varchar(11) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '责任人联系方式',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `check_time` datetime NULL DEFAULT NULL COMMENT '检查时间',
  `status` tinyint(1) NOT NULL DEFAULT 0 COMMENT '状态 0禁 1启用',
  `delete_flag` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除 0没删 1删',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

