-- ----------------------------
-- Table structure for vd_fire
-- ----------------------------
DROP TABLE IF EXISTS `vd_fire`;
CREATE TABLE `vd_fire`  (
  `id` bigint(20) NOT NULL,
  `pic` bigint(20) NULL DEFAULT NULL COMMENT '火灾照片',
  `start_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `place_id` bigint(20) NOT NULL COMMENT '地点外键',
  `reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '起火原因',
  `situation` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '伤亡情况',
  `prob` float(10, 3) NOT NULL COMMENT '起火概率',
  `fire_flag` tinyint(1) NULL DEFAULT NULL COMMENT '是否起火',
  `smoke_prob` float(10, 3) NULL DEFAULT NULL COMMENT '烟雾概率',
  `smoke_flag` tinyint(1) NULL DEFAULT NULL COMMENT '是否有烟',
  `video_id` bigint(20) NOT NULL COMMENT '视频id',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户id',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

