-- ----------------------------
-- Table structure for vd_video
-- ----------------------------
DROP TABLE IF EXISTS `vd_video`;
CREATE TABLE `vd_video`  (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint(20) UNSIGNED NOT NULL COMMENT '用户id',
  `video_url` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '存储地址',
  `upload_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '上传时间',
  `status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '视频处理状态（如：0:待处理、1:处理中、2:已完成）',
  `title` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '视频标题',
  `thumbnail` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '缩略图地址',
  `extension` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '文件扩展名',
  `processed_url` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '处理后的地址',
  `fire_probability` double NULL DEFAULT NULL COMMENT '火灾概率',
  `smoke_probability` double NULL DEFAULT NULL COMMENT '烟雾概率',
  `process_time` datetime NULL DEFAULT NULL COMMENT '处理时间',
  `place_id` bigint(20) NULL DEFAULT NULL COMMENT '地点id',
  `d_time` int(11) NULL DEFAULT NULL COMMENT '视频时长(s)',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `vd_video_vd_user_FK`(`user_id`) USING BTREE,
  CONSTRAINT `vd_video_vd_user_FK` FOREIGN KEY (`user_id`) REFERENCES `vd_user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 3801514449121 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = DYNAMIC;

